function cryptoFreeze(value){if(value&&typeof value==='object'&&!Object.isFrozen(value)){Object.values(value).forEach(cryptoFreeze);Object.freeze(value);}return value;}
// Typed inputs are consumed before any reference request/ticket is constructed.
// Contextualizing replays construction; it never edits issued signed/ciphertext
// objects or the exported base-definition registry in place.
function cryptoContext(context={}){
  const resolved=resolveKerberosContext(context,'HTTP/intranet.a.example');
  return Object.freeze({...resolved,tgtTarget:'krbtgt/'+resolved.realm});
}
function cryptoFixture(meta,actorIds,initialState={},options={}){
  const context=options.context;
  const prefix='crypto'+meta.id.replace(/^lab-/,'').split('-').map(s=>s[0].toUpperCase()+s.slice(1)).join('');
  const defs={},refs={},steps=[];
  const add=(suffix,name,meaning,origin,purpose,value,options={})=>{
    const id=prefix+suffix;
    defs[id]=labAttribute(name,meaning,origin,purpose,value,options.standard||meta.standard,options.source||meta.source);
    refs[id]={instanceId:meta.id+':'+(options.object||suffix.toLowerCase())+':1',fieldPath:options.path||name,representation:options.representation||'decoded-local',creator:options.creator===null?undefined:options.creator||'cryptoClient',holders:options.holders||['cryptoClient'],inspectors:options.inspectors||options.holders||['cryptoClient'],value,sourceEventId:options.static?'initial':null};
    defs[id].localOnly=!!options.localOnly;defs[id].sensitive=!!options.sensitive;
    return id;
  };
  const op=(ids,kind,actorId,detail,carriedAs,overrides={})=>labOp(ids,kind,actorId,detail,carriedAs).map(o=>({...o,...refs[o.attributeId],...overrides}));
  const wire=(ids,from,to,detail,carriedAs)=>labWire(ids,from,to,detail,carriedAs).map(o=>({...o,...refs[o.attributeId],representation:refs[o.attributeId].representation==='opaque-ciphertext'?'opaque-ciphertext':'wire-encoded'}));
  const p=id=>labP(defs[id].name,refs[id].value,undefined,id);
  const put=(path,value)=>({op:'put',path,value});
  const stage=(key,title,from,to,summary,detail,operations,payload=[],effects=[],checks=[],channel)=>{
    const eventId=meta.id+'-'+key;
    for(const operation of operations){const ref=refs[operation.attributeId];if(!ref.sourceEventId&&['create','derive'].includes(operation.kind))ref.sourceEventId=eventId;operation.sourceEventId=ref.sourceEventId||eventId;operation.exactValueRef=operation.instanceId+'@'+operation.sourceEventId+'#'+operation.fieldPath;}
    const s=labStep(eventId,title,from,to,'authenticate',channel||(from===to?'internal':'backchannel'),summary,detail,[...new Set(operations.map(o=>o.attributeId))],payload,checks,operations);
    s.labCryptoStage=key;s.protocolEffects=effects;s.eventType=channel==='human'?'human':channel==='local-ipc'?'localIPC':from===to?'localOperation':'network';
    s.attributeValues=Object.fromEntries(operations.map(o=>[o.attributeId,o.value]));steps.push(s);return s;
  };
  const finish=()=>{
    const realmId=add('Realm','realm (KDC-REQ-BODY)','The Kerberos realm selected for this fixture.','Configured domain/realm context before the exchange.','Routes the KDC request and is checked against the accepted reply.',context.realm,{object:'realm-configuration',path:'KDC-REQ-BODY.realm',creator:'cryptoKdc',holders:['cryptoKdc','cryptoClient'],static:true});
    const realmOwner=meta.variant==='bootstrap'?'cryptoComputer':'cryptoClient';
    steps[0].attributeOperations.push(...op([realmId],'use',realmOwner,'Uses the selected configured Kerberos realm.'));
    steps[0].fields.push(realmId);steps[0].attributeValues[realmId]=context.realm;
    const spnEntry=Object.entries(defs).find(([,def])=>def.name==='sname (service request)');
    const createdCredentialPaths=steps.flatMap(step=>step.protocolEffects).filter(effect=>effect.op==='put'&&effect.value&&typeof effect.value==='object');
    const runtimeBindings=[{field:'kerberosRealm',attributeId:realmId,actorId:'cryptoKdc',label:'Kerberos realm',example:context.realm,regeneratesFixture:true,statePaths:createdCredentialPaths.filter(effect=>Object.hasOwn(effect.value,'crealm')).map(effect=>effect.path+'.crealm')}];
    if(spnEntry)runtimeBindings.push({field:'servicePrincipal',attributeId:spnEntry[0],actorId:actorIds.includes('cryptoService')?'cryptoService':'cryptoKdc',label:'Service principal',example:context.servicePrincipal,regeneratesFixture:true,statePaths:createdCredentialPaths.filter(effect=>effect.path==='credentials.service'&&Object.hasOwn(effect.value,'sname')).map(effect=>effect.path+'.sname')});
    const componentFor=step=>meta.id.startsWith('lab-ad-fast-tgs-')||step.labCryptoStage.startsWith('tgs-')?'cryptoTgs':'cryptoAs';
    const creators=new Map(),held=new Map(),components=new Set();
    for(const step of steps){const component=componentFor(step);for(const key of ['from','to'])if(step[key]==='cryptoKdc'){step[key]=component;components.add(component);}for(const operation of step.attributeOperations){if(operation.actorId==='cryptoKdc'){operation.actorId=component;components.add(component);}if(operation.sourceEventId!=='initial'&&['create','derive'].includes(operation.kind)&&!creators.has(operation.instanceId))creators.set(operation.instanceId,operation.actorId);}}
    for(const step of steps)for(const operation of step.attributeOperations){
      const ref=refs[operation.attributeId];operation.creator=creators.get(operation.instanceId)||operation.creator;
      if(!held.has(operation.instanceId))held.set(operation.instanceId,new Set(operation.sourceEventId==='initial'?operation.holders:[]));
      if(['create','derive','use','verify','receive','store'].includes(operation.kind))held.get(operation.instanceId).add(operation.actorId);
      operation.holders=[...held.get(operation.instanceId)];
      if(operation.inspectors.includes('cryptoKdc')&&['cryptoAs','cryptoTgs'].includes(operation.actorId))operation.inspectors=[...new Set([...operation.inspectors,operation.actorId])];
      operation.exactValueRef=operation.instanceId+'@'+(operation.sourceEventId||'initial')+'#'+operation.fieldPath;
      if(!operation.sourceEventId)operation.sourceEventId=ref.sourceEventId||'initial';
    }
    actorIds=[...new Set([...actorIds,...components])];
    const used=new Set(steps.flatMap(s=>s.fields));for(const id of Object.keys(defs))if(!used.has(id))delete defs[id];
    if(options.register!==false)Object.assign(CRYPTOLAB_ATTRIBUTES,defs);
    const actorSpecs=Object.fromEntries(actorIds.map(id=>[id,cryptoActorSpecs[id]]));
    if(actorSpecs.cryptoService)actorSpecs.cryptoService={...actorSpecs.cryptoService,role:'Kerberos acceptor · '+context.servicePrincipal};
    if(components.size===1){const child=[...components][0];actorSpecs[child]={...actorSpecs[child],position:cryptoActorSpecs.cryptoKdc.position};}
    const state={protocolClock:1791381600,credentials:{},keys:{},checks:{},knowledge:{client:{},kdc:{}},sessions:{},policy:{},...initialState};
    const positions=Object.fromEntries(actorIds.map(id=>[id,actorSpecs[id].position]));
    const model=labScenario({workspace:'kerberos',family:'ad-ds',protocol:'kerberos',architecture:'web',category:meta.lesson==='AD-03'?'AD DS · PKINIT':'AD DS · FAST / armoring',hasPerson:true,status:'reference',supportNote:'RFC/MS-specified symbolic reference. No observed Windows trace is claimed. Pin Windows build, certificate/enctype/KDF profile and configuration before using this as a literal product trace.',...meta,featured:meta.variant==='success',initialState:cryptoFreeze(state),positions,actorPositions:positions,runtimeBindings},defs,steps,actorSpecs);
    model.contextualize=next=>options.rebuild(meta.variant,next,false);
    return model;
  };
  return {meta,context,defs,refs,steps,add,op,wire,p,put,stage,finish};
}

