  b.stage('card-sign','Sign with the card-held private key','cryptoCard','cryptoCard','The card proves possession of Alice’s signing key.','A signature over the chosen AuthPack is returned; the private signing key is never returned.',[...b.op([f.SigningKey,f.AuthPack],'use','cryptoCard','Uses the local private key over the exact AuthPack.'),...b.op([f.SignedAuthPack],'derive','cryptoCard','Produces the CMS signature for this AuthPack.')],[],[b.put('checks.cardSigned',true)]);
  b.stage('signature-result','Return the public signing result','cryptoCard','cryptoClient','The workstation receives the signed request proof.','Public certificates accompany the selected CMS fixture; neither private signing material nor PIN is included.',b.wire([f.SignedAuthPack,f.UserCertificate],'cryptoCard','cryptoClient','Returns public CMS signing output and public certificate chain.','local credential API'),[b.p(f.SignedAuthPack)],[],[], 'local-ipc');
  b.stage('as-request','Send AS-REQ with PA-PK-AS-REQ','cryptoClient','cryptoKdc','The KDC receives Alice’s signed initial authentication request.','The outer request body and CMS signedAuthPack are separate objects. AuthPack fields are signed and readable; the local private keys are absent.',b.wire([f.Body,f.BodyNonce,f.SignedAuthPack,f.UserCertificate],'cryptoClient','cryptoKdc','Carries the AS request body and signed PKINIT padata.','AS-REQ / PA-PK-AS-REQ'),[b.p(f.Body),b.p(f.SignedAuthPack)]);
  b.stage('request-check','Validate the signature, request binding and strong identity','cryptoKdc','cryptoKdc','The KDC checks who signed, which request was signed and which account it belongs to.','Certificate chain/EKU/revocation and strong SID or explicit issuer/serial mapping are independent gates. paChecksum binds the exact body; signed time/nonce enter freshness/replay checks. A SAN UPN alone is not strong binding.',[...b.op([f.SignedAuthPack,f.AuthPack,f.Ctime,f.Cusec,f.PkNonce,f.Checksum,f.Body,f.UserCertificate,f.CertificateTrust,f.StrongMapping],'verify','cryptoKdc','Validates the signed request and the configured certificate/account binding.')],[b.p(f.CertificateTrust),b.p(f.StrongMapping)],[b.put('checks.pkinitSignature',true),b.put('checks.pkinitTrust',variant!=='trust'),b.put('checks.pkinitMapping',variant!=='binding')],['CMS signature and request-body checksum','Certificate chain / purpose / revocation','Freshness and strong account binding']);
  if(['binding','trust'].includes(variant)){
    b.stage('kdc-reject','Reject before creating reply keys or tickets','cryptoKdc','cryptoKdc',variant==='binding'?'The signature can be valid while account binding is insufficient.':'The credential chain is not accepted by this KDC.','The KDC creates no TGT or DH reply for this rejected request. This symbolic fixture leaves the exact product-specific wire error code unclaimed.',b.op([f.Rejection],'create','cryptoKdc','Records the selected rejection at the KDC.'),[b.p(f.Rejection)],[b.put('knowledge.kdc.failure',variant==='binding'?'strong-binding':'client-certificate-trust')]);
    b.stage('reject-result','Return the selected failed-login result','cryptoKdc','cryptoClient','The workstation learns that this login failed.','This is a reference failure result; the deployment trace determines its literal KRB-ERROR code.',b.wire([f.Rejection],'cryptoKdc','cryptoClient','Returns the selected authentication failure result.','reference error result'),[b.p(f.Rejection)],[b.put('knowledge.client.failure',variant==='binding'?'strong-binding':'client-certificate-trust')]);
    return b.finish();
  }
  b.stage('kdc-dh','Derive the KDC reply key and sign its fresh DH response','cryptoKdc','cryptoKdc','The KDC computes its local DH secret, then creates two different keys for different jobs.','The DH shared secret feeds the selected KDF for the AS reply key. A separately generated TGT session key goes into EncASRepPart; the TGT ticket is encrypted for krbtgt. KDCDHKeyInfo.nonce binds the PKAuthenticator nonce, not the request-body nonce.',[...b.op([f.KdcDhPrivate,f.TgtSessionKey,f.Tgt,f.AsReplyNonce],'create','cryptoKdc','Creates fresh server DH material and a separate user-TGT credential.'),...b.op([f.ClientPublic,f.KdcSigningKey],'use','cryptoKdc','Uses client public DH data and the local KDC signing key.'),...b.op([f.KdcPublic,f.DhReplyNonce,f.SharedSecret,f.ReplyKey,f.SignedDh,f.AsEncPart],'derive','cryptoKdc','Computes local DH/KDF result, signs KDCDHKeyInfo and encrypts the client reply.')],[b.p(f.DhReplyNonce),b.p(f.AsReplyNonce)],[b.put('keys.asReplyKdc',{instanceId:b.refs[f.ReplyKey].instanceId,method:'fresh-DH KDF'}),b.put('checks.pkinitKdcAccepted',true)]);
  b.stage('as-response','Return AS-REP and the signed KDC DH material','cryptoKdc','cryptoClient','The client receives public DH proof and two encrypted objects.','The client cannot read the TGT ticket ciphertext. AS-REP.enc-part can be decoded only after it validates the KDC and derives the reply key.',b.wire([f.SignedDh,f.KdcCertificate,f.Tgt,f.AsEncPart],'cryptoKdc','cryptoClient','Returns PKINIT signed DH proof, opaque ticket and encrypted client reply.','AS-REP / PA-PK-AS-REP'),[b.p(f.SignedDh),b.p(f.Tgt),b.p(f.AsEncPart)]);
  b.stage('kdc-reply-check','Validate the KDC’s signed DH response','cryptoClient','cryptoClient','The workstation checks its peer before using the DH reply.','Check the KDC certificate and signature, permitted DH parameters and KDCDHKeyInfo.nonce=72002. The separately encrypted AS body still needs validation later.',b.op([f.KdcCertificate,f.SignedDh,f.KdcPublic,f.DhReplyNonce,f.PkNonce],'verify','cryptoClient','Verifies KDC trust, the signed DH object and exact PKAuthenticator-nonce binding.'),[b.p(f.DhReplyNonce),b.p(f.PkNonce)],[b.put('checks.kdcCertificateTrust',variant!=='kdc-trust')],['Trusted KDC certificate and signature','Permitted DH parameters','Exact signed nonce binding']);
