  if(['unsupported-dc','optional-fallback'].includes(variant))set(f.Capability,'Selected realm/DC lacks usable FAST capability');
  if(variant==='optional-fallback')set(f.Policy,'FAST optional; client and KDC explicitly permit an ordinary password AS path');
  if(variant==='checksum')set(f.ReqChecksum,'Checksum{mismatched DER outer KDC-REQ-BODY; armor_key; usage=50}');
  if(variant==='challenge')set(f.Challenge,'Encrypted PA-ENC-TS-ENC{fresh timestamp}; incorrect user challenge-key proof; usage=54');
  b.refs[f.OriginalReplyKey]={...b.refs[f.OriginalReplyKey],instanceId:b.refs[f.LongTermKey].instanceId,fieldPath:b.refs[f.LongTermKey].fieldPath,value:b.refs[f.LongTermKey].value,creator:b.refs[f.LongTermKey].creator,holders:b.refs[f.LongTermKey].holders,inspectors:b.refs[f.LongTermKey].inspectors,sourceEventId:'initial'};
  b.defs[f.OriginalReplyKey].example=b.refs[f.LongTermKey].value;
  if(variant==='bootstrap'){b.refs[f.ArmorTicket].sourceEventId=null;b.refs[f.ArmorTicketKey].sourceEventId=null;}
  if(variant==='bootstrap')return cryptoFastBootstrap(b,f);
  b.stage('prerequisites','Check client policy, realm/DC capability and armor availability','cryptoClient','cryptoClient','The workstation checks whether this required protected exchange is possible.','Computer/user contexts remain distinct. Suitable DC discovery, domain/client configuration and computer-TGT availability are explicit prerequisites; required FAST cannot silently fall back.',b.op([f.Policy,f.Capability],'verify','cryptoClient','Checks the selected configured FAST prerequisites.'),[b.p(f.Policy),b.p(f.Capability)],[b.put('checks.fastPrerequisites',variant!=='unsupported-dc')],['Client awareness / domain configuration','Suitable FAST-capable DC','Usable computer armor credential']);
  if(variant==='unsupported-dc'){
    b.stage('prerequisite-denied','Stop locally: required FAST has no suitable DC','cryptoClient','cryptoClient','The client cannot perform the required protected sign-in.','No user AS request is sent to an unsupported DC, and no user credential is issued. The existing computer credential remains in its own context.',b.op([f.Failure],'create','cryptoClient','Records the configured prerequisite rejection.'),[],[b.put('knowledge.client.failure','required-fast-no-suitable-dc')]);return b.finish();
  }
