  if(variant==='required-armor'){
    b.stage('unarmored-request','Send the selected unarmored user AS attempt','cryptoClient','cryptoKdc','The KDC receives a user request without its required FAST armor.','This deliberately failing fixture is a user AS exchange. The computer bootstrap exception does not apply.',[...b.op([f.OuterBody],'create','cryptoClient','Creates the unarmored user request.'),...b.wire([f.OuterBody],'cryptoClient','cryptoKdc','Sends the unarmored user request without PA-FX-FAST.','AS-REQ')],[b.p(f.OuterBody)]);
    b.stage('enforce','Reject the user request under enforced armor policy','cryptoKdc','cryptoKdc','The KDC refuses this unprotected user authentication.','It creates no user TGT or reply key; the preexisting computer TGT remains. Literal Windows error shape is a version/configuration trace gate.',[...b.op([f.Policy],'verify','cryptoKdc','Applies user AS enforcement; excludes the computer bootstrap exception.'),...b.op([f.Failure],'create','cryptoKdc','Records absent required armor.')],[],[b.put('knowledge.kdc.failure','required-armor-absent')]);
    b.stage('enforce-result','Return the armor-policy rejection','cryptoKdc','cryptoClient','The client learns that the unarmored request was refused.','An error does not carry strengthen-key or finished; no user credential is cached.',b.wire([f.Failure],'cryptoKdc','cryptoClient','Returns this reference policy failure.','KRB-ERROR reference result'),[],[b.put('knowledge.client.failure','required-armor-absent')]);return b.finish();
  }
