  b.stage('user-credential','Supply Alice’s user credential locally','cryptoUser','cryptoClient','Alice provides her own credential to the workstation.','The workstation derives Alice’s Kerberos long-term key locally. Her password is not a KDC packet, and the computer TGT cannot substitute for her user proof.',[...b.op([password],'create','cryptoUser','Provides the local workstation credential input.'),...b.op([password],'use','cryptoClient','Accepts the local input through the trusted sign-in UI.'),...b.op([f.LongTermKey],'derive','cryptoClient','Derives the user key under the selected account/enctype profile.')],[b.p(password)],[b.put('keys.userLongTermClient',{instanceId:b.refs[f.LongTermKey].instanceId})],[], 'human');
