  if(missingStrengthen){b.refs[f.ReplyEncPart].value='Encrypted EncTGSRepPart in original TGS subkey (malformed unstrengthened reply fixture)';b.defs[f.ReplyEncPart].example=b.refs[f.ReplyEncPart].value;}
  const innerReply=[f.ReplyNonce,f.Finished,f.TicketChecksum,...(missingStrengthen?[]:[f.Strengthen])];
  b.stage('protect-response','Create the protected response and strengthened client reply','cryptoKdc','cryptoKdc','The KDC returns authenticated protection metadata and a separately protected ticket credential.','enc-fast-rep uses armor_key and usage 52; finished.ticket-checksum binds exact ticket bytes with usage 53. '+(tgs?'TGS strengthening is mandatory and starts from the original authenticator subkey.':'The selected PA-ENCRYPTED-CHALLENGE AS factor requires reply-key strengthening before ticket issuance and a reciprocal encrypted challenge with the distinct KDC-direction key.')+' The new ticket-session key is independent of all reply/armor keys.',[
    ...b.op([f.IssuedTicket,f.IssuedSessionKey,...innerReply],'create','cryptoKdc','Creates the credential and protected successful FAST response fields.'),
    ...(!tgs?[...b.op([f.KdcChallengeKey,f.KdcChallenge],'derive','cryptoKdc','Derives KDC-direction challenge key and encrypted reciprocal proof with usage 55.')]:[]),
    ...b.op([f.OriginalReplyKey,f.ArmorKey,f.Usage52,f.Usage53],'use','cryptoKdc','Uses separate reply and armor inputs with response/finished key usages.'),
    ...b.op([...(missingStrengthen?[]:[f.FinalReplyKey]),f.EncRep,f.FastResponse,f.ReplyEncPart],'derive','cryptoKdc','Protects FAST response contents and the separate client key envelope.')],[],[b.put('checks.kdcUserAccepted',true),b.put('keys.originalReplyKdc',{instanceId:b.refs[f.OriginalReplyKey].instanceId,source:tgs?'TGS authenticator subkey':'user account long-term key'}),...(missingStrengthen?[]:[b.put('keys.finalReplyKdc',{instanceId:b.refs[f.FinalReplyKey].instanceId,method:'CF2 strengthenkey/replykey'})])]);
  const wireIds=[f.IssuedTicket,f.ReplyEncPart,...(variant==='missing-response'?[]:[f.FastResponse,f.EncRep])];
  b.stage('fast-response','Return '+(tgs?'TGS-REP':'AS-REP')+' with the selected protected containers','cryptoKdc','cryptoClient',variant==='missing-response'?'The reply arrives without the required protected FAST envelope.':'The client receives a ticket and two different encrypted reply objects.','The ticket is encrypted for its target; KDC-REP.enc-part is protected by the client reply key; enc-fast-rep is protected by armor. Decoded strengthen-key and session keys are not exposed wire fields.',b.wire(wireIds,'cryptoKdc','cryptoClient','Returns this fixed reply fixture with its exact selected containers.',tgs?'TGS-REP':'AS-REP'),wireIds.map(b.p));
  if(variant==='missing-response'){
    b.stage('reply-policy-denied','Reject the missing required FAST reply','cryptoClient','cryptoClient','The configured client policy refuses an unprotected result.','No returned credential is accepted or cached. The earlier computer TGT remains; required protection cannot silently downgrade.',[...b.op([f.Policy],'verify','cryptoClient','Requires the protected FAST reply.'),...b.op([f.Failure],'create','cryptoClient','Records missing protected response.')],[],[b.put('checks.protectedResponse',false),b.put('knowledge.client.failure','missing-protected-response')]);return;
  }
  b.stage('decode-response','Decode and validate nonce, identity and ticket binding','cryptoClient','cryptoClient','The client opens the FAST envelope and checks it belongs to this request and ticket.','Use armor_key and usage 52 to decode KrbFastResponse. Check nonce, finished identity/time and ticket-checksum with usage 53. '+(tgs?'Require strengthen-key; an error response cannot contain it.':'Require strengthen-key for the selected PA-ENCRYPTED-CHALLENGE factor; validate the reciprocal challenge with the KDC-direction key and usage 55.')+' These checks occur before accepting the new credential.',[
    ...b.op([f.EncRep,f.ArmorKey,f.Usage52],'use','cryptoClient','Locally decodes the protected response.'),
    ...b.op([f.ReplyNonce,f.Nonce,f.Finished,f.TicketChecksum,f.IssuedTicket,f.Usage53,...(!missingStrengthen?[f.Strengthen]:[])],'verify','cryptoClient','Checks exact request nonce, identity, returned ticket bytes and required response fields.'),
    ...(!tgs?[...b.op([f.KdcChallengeKey],'derive','cryptoClient','Derives the separate reciprocal challenge key.'),...b.op([f.KdcChallenge,f.KdcChallengeKey],'verify','cryptoClient','Validates the KDC encrypted challenge with usage 55.')]:[])],
    [b.p(f.ReplyNonce),b.p(f.Nonce)],
    [b.put('checks.protectedResponse',true),b.put('checks.fastReplyNonce',variant!=='response-nonce'),b.put('checks.fastFinishedTicket',variant!=='ticket-binding'),b.put('checks.fastStrengthenPresent',!missingStrengthen)],['Protected response decoded','Request nonce matches','Finished identity and exact ticket checksum',tgs?'Required FAST TGS strengthening':'Required PA-ENCRYPTED-CHALLENGE AS strengthening']);
  const reason=variant==='response-nonce'?'protected-response-nonce':variant==='ticket-binding'?'finished-ticket-binding':missingStrengthen?'missing-tgs-strengthen-key':null;
